/* ---------- links, selection, caret, focus, semantic ---------- */
a, a *, [role="link"] {
  color: var(--ds-blue) !important;
  -webkit-text-fill-color: var(--ds-blue) !important;
  text-decoration-color: var(--ds-blue) !important;
}
a:hover, a:hover * {
  color: var(--ds-blue-2) !important;
  -webkit-text-fill-color: var(--ds-blue-2) !important;
}
::selection {
  background: var(--ds-yellow) !important;
  color: var(--ds-black) !important;
  -webkit-text-fill-color: var(--ds-black) !important;
}
