  outline: 2px solid var(--ds-black) !important;
  outline-offset: 0 !important;
}
/* semantic, only where stated: FHWA red, pure-white legend (§1b) */
[aria-invalid="true"], [role="alert"][data-severity="error"] {
  background-color: var(--ds-destructive) !important;
  color: #FFFFFF !important;
  -webkit-text-fill-color: #FFFFFF !important;
}

/* ---------- scrollbars ---------- */
* {
  scrollbar-color: var(--ds-dark) var(--ds-light);
}
::-webkit-scrollbar {
  width: 14px;
  height: 14px;
  background: var(--ds-light);
}
::-webkit-scrollbar-thumb {
  background: var(--ds-dark);
  border: 0;
}
::-webkit-scrollbar-corner {
  background: var(--ds-light);
}

/* ---------- type ---------- */
/* the two faces, WITHOUT !important. The sheet is injected last, so it wins ties against a site's
   own body font, but any element a site gives a font by class — which is how icon fonts are
   applied — keeps it. With !important, every icon glyph in a button or link rendered as tofu. */
html, body, p, h1, h2, h3, h4, h5, h6, li, dt, dd, td, th, label, legend, figcaption, summary, blockquote, caption, a, button, input, select, textarea, option, [role="button"], [role="link"], [role="tab"], [role="menuitem"], [role="option"] {
  font-family: var(--ds-ui);
}
code, pre, kbd, samp, tt, code *, pre *, .monospace, [class*="mono"] {
  font-family: var(--ds-mono);
}

/* ---------- content is content ---------- */
img, video, canvas, picture, svg {
  filter: none !important;
  opacity: 1 !important;
}
